from rcb_client import Robot
import numpy as np
r=Robot();o=r.get_obs(cameras=['robot0_agentview_right'],include_depth=True,video='none');cam=o.meta['cameras']['robot0_agentview_right'];T=np.array(cam['cam2world_gl']);K=np.array(cam['intrinsic_cv']);d=o.depth['robot0_agentview_right'][0].astype(float);rgb=o.last['robot0_agentview_right'];P=np.array(o.meta['proprio']['now']);
for name,p in [('eef',P[26:29]),('headOld',np.array([1.4573368,-3.3985712,1.4394])),('box top',np.array([1.41,-3.44,1.43])),('bar',np.array([1.48,-3.35,1.45]))]:
 c=np.linalg.inv(T)@np.r_[p,1];print(name,'pix',(K[0,0]*c[0]/-c[2]+K[0,2],K[1,1]*(-c[1])/-c[2]+K[1,2]))
for y in [78,85,92,100,108,116,124,132]:
 print(y,[(x,tuple(rgb[y,x].tolist()),round(float(d[y,x]),3)) for x in [150,160,170,180,190,200]])
